function filterTools(){const t=document.getElementById("toolSearch").value.toLowerCase().trim();document.querySelectorAll(".tool-card").forEach(e=>{const o=e.textContent.toLowerCase();e.style.display=o.includes(t)?"block":"none"})}function filterByCategory(t){document.querySelectorAll(".tag-btn").forEach(t=>t.classList.remove("active")),event.currentTarget.classList.add("active");const e=document.querySelectorAll(".tool-card");"all"===t?e.forEach(t=>t.style.display="block"):e.forEach(e=>{e.style.display=e.getAttribute("data-category")===t?"block":"none"})}